/* ==========================================================================
   seed-data.js — sample records used the first time a page loads (and when
   CMS.dev.resetAll() is called). Real data is never overwritten by this file.
   Lists are shown newest-first by `createdAt`, so the seed rows are written in
   the order they should appear on screen.
   ========================================================================== */
window.CMS = window.CMS || {};

CMS.seed = (function () {
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  /* 'YYYY-MM-DD' for today + offset days (local time) */
  function day(offset) {
    var d = new Date();
    d.setDate(d.getDate() + offset);
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  }
  /* decreasing timestamps keep the seed order when sorted newest-first */
  function stamp(i) { return new Date(Date.now() - i * 60000).toISOString(); }
  function p(text) { return '<p>' + text + '</p>'; }

  var ALL = CMS.config.allCampuses;

  /* Sample pictures (small JPEGs, cropped from the UI mockups) */
  var IMG = {
    A1: 'data:image/jpeg;base64,',
    A2: 'data:image/jpeg;base64,',
    N1: 'data:image/jpeg;base64,',
    N2: 'data:image/jpeg;base64,',
    N3: 'data:image/jpeg;base64,',
    N4: 'data:image/jpeg;base64,',
    N5: 'data:image/jpeg;base64,',
    N6: 'data:image/jpeg;base64,',
    EVENT: 'data:image/jpeg;base64,'
  };
  function list3(a, b, c) { return '<ul><li>' + a + '</li><li>' + b + '</li><li>' + c + '</li></ul>'; }

  /* ---- News. The first five rows are the admin mockup rows; the rest feed the public News page.
     Row: [title, category, author, campus, published, status, summary, content, image, attachment] */
  function news() {
    var KEY = 'This sample article is written for testing. Replace it with the content written in the CMS.';
    var rows = [
      ['PSU Opens Enrollment for Second Semester', 'University News', 'John Rich Tagle', ALL, '2026-10-28', 'published', 'Registration for the second semester is now open for all programs.', p('Registration for the second semester is now open. Students are advised to check their schedules and settle their accounts before the deadline.'), IMG.A1],
      ['Engineering Students Win National Design Contest', 'Awards', 'Edrian Baccarat', 'Urdaneta', '2026-10-24', 'published', 'A team of engineering students took first place in a national design competition.', p('The team presented a low-cost water filtration prototype and beat finalists from 18 other universities.'), IMG.A2],
      ['Research Congress Call for Papers', 'Research', 'Paul Douh', ALL, '2026-10-20', 'pending', 'Researchers are invited to submit abstracts for the annual Research Congress.', p('Abstracts may be submitted until the end of next month. Accepted papers will be presented in parallel sessions.')],
      ['Intramurals 2026 Highlights', 'Student Life', 'Aula Efseven', 'Lingayen-Main', '2026-10-15', 'draft', 'A look back at the best moments of this year\'s intramurals.', p('Colleges competed in basketball, volleyball, athletics and chess over five days.')],
      ['Library Digitization Project Completed', 'University News', 'Viexi Arwan', 'Urdaneta', '2026-09-30', 'archived', 'Thousands of theses and journals are now available online.', p('The library finished scanning its thesis collection and added it to the online catalog.')],
      ['PSU produces 3 topnotchers in Fisheries Professionals Licensure Exam', 'Awards', 'Admin User', 'Urdaneta', '2026-10-07', 'published', 'Three graduates placed among the topnotchers of the October 2026 Fisheries Professional Licensure Examination.',
        p('Three graduates of the Bachelor of Science in Fisheries program placed among the topnotchers of the October 2026 licensure examination, bringing honor to the university and the Urdaneta City Campus.') +
        list3('Three topnotchers from one program in a single examination', 'A passing rate well above the national average', 'Review classes and faculty mentoring credited for the results') +
        p('The university congratulates the new licensed professionals and their families.'), IMG.N1,
        { name: 'Official-Results.pdf', size: 1258291, type: 'pdf' }],
      ['NEUST benchmarks PSU\'s EOMS best practices', 'University News', 'Admin User', 'Lingayen-Main', '2026-10-06', 'published', 'A team from NEUST visited the Main Campus to learn how PSU runs its quality management system.',
        p('Representatives from Nueva Ecija University of Science and Technology visited the Lingayen-Main campus to study the university\'s Educational Organizations Management System (EOMS).') +
        list3('Overview of the multi-campus ISO 9001:2015 certification', 'Sharing of document control and audit practices', 'Plans for a follow-up exchange next year') +
        p('The visit is part of an ongoing effort to share quality practices among state universities.'), IMG.N2],
      ['PSU roars loud at Timpuyog ti Amianan 2026', 'Student Life', 'Admin User', ALL, '2026-10-06', 'published', 'Student delegates from across PSU campuses brought home medals from the regional cultural and sports meet.',
        p('Delegates from across PSU campuses represented the university at Timpuyog ti Amianan 2026, joining athletes and performers from universities in Northern Luzon.') +
        list3('Medals in sports and the arts', 'Strong crowd support from students and alumni', 'Preparations already under way for next year') +
        p('The university thanks the coaches, trainers and student leaders who made the team possible.'), IMG.N3],
      ['PSU produces Top 8 in Civil Engineering exam', 'Awards', 'Admin User', 'Urdaneta', '2026-10-03', 'published', 'The Urdaneta City Campus ranked among the top performing schools in the September 2026 Civil Engineers Licensure Examination.',
        p('A graduate of the Urdaneta City Campus placed 8th in the September 2026 Civil Engineers Licensure Examination, and the campus ranked 4th among top performing schools.') +
        list3('A Top 8 placer in the national rankings', 'Rank 4 among top performing schools', 'Continued investment in review programs') +
        p('Congratulations to the graduates and the College of Engineering.'), IMG.N4],
      ['PSU advances research commercialization with a new grant', 'Research', 'Admin User', 'Lingayen-Main', '2026-10-02', 'published', 'A PHP 4.9 million IMPACT NXT grant from DOST-PCIEERD will help move university research to the market.',
        p('Pangasinan State University received a PHP 4.9 million IMPACT NXT grant from DOST-PCIEERD to support the commercialization of research outputs.') +
        list3('Funding for prototype testing and intellectual property work', 'Support for researcher training and business mentoring', 'A pipeline of projects ready for industry partners') +
        p('The university is one of the higher education institutions selected under the program.'), IMG.N5],
      ['PSU receives conferment for Center of Excellence status', 'University News', 'Admin User', ALL, '2026-10-01', 'published', 'The Bayambang Campus was recognized as a Regional Teacher Education Center of Excellence.',
        p('The Commission on Higher Education conferred the 2026 Regional Teacher Education Center of Excellence status on the PSU Bayambang Campus.') +
        list3('Recognition of the quality of the teacher education program', 'Access to additional support for faculty and students', 'A boost to the university\'s standing in the region') +
        p('The university thanks the faculty and staff whose work made this recognition possible.'), IMG.N6],
      ['Faculty Research Grants Announced', 'Research', 'Admin User', 'Lingayen-Main', '2026-09-12', 'published', 'Twelve research proposals were selected for funding this year.', p('The grants cover equipment, fieldwork and publication costs. Recipients will present their progress at the next Research Congress.')],
      ['Basketball Team Advances to Regional Finals', 'Student Life', 'Admin User', 'Alaminos', '2026-08-29', 'published', 'The varsity team won its semifinal match by 12 points.', p('The finals will be held next month. Students and alumni are invited to cheer for the team.')],
      ['Science Fair Showcases Student Inventions', 'Student Life', 'Admin User', 'Infanta', '2026-08-10', 'pending', 'More than 60 projects were displayed at this year\'s science fair.', p('Judges awarded prizes in environment, health and technology categories.')]
    ];
    return rows.map(function (r, i) {
      return { id: 'news_seed_' + (i + 1), title: r[0], category: r[1], author: r[2], campus: r[3], publishedAt: r[4],
               status: r[5], shortDescription: r[6], content: r[7], image: r[8] || '', attachment: r[9] || null,
               createdAt: stamp(i), updatedAt: stamp(i) };
    });
  }

  /* ---- Announcements. The first four rows are the admin mockup rows; the rest feed the public page.
     Dates of the public rows are relative to today so they stay active.
     Row: [title, category, author, campus, priority, posted, expires, status, content, attachment] */
  function announcements() {
    var rows = [
      ['Midterm Examination Schedule', 'Academic', 'Registrar', ALL, 'normal', '2026-10-27', '2026-11-15', 'published', p('The midterm examination schedule has been posted. Please check your college bulletin board and the student portal.')],
      ['Suspension of Classes \u2013 Typhoon', 'Advisory', 'Admin User', ALL, 'urgent', '2026-10-22', '2026-10-25', 'published', p('Due to the approaching tropical cyclone and the weather advisory issued by PAGASA, classes at all levels in all PSU campuses are suspended on October 23, 2026.') + p('Faculty and staff are advised to monitor official university channels for updates on the resumption of classes and make-up schedules.'),
       { name: 'Memorandum-Class-Suspension.pdf', size: 217088, type: 'pdf' }],
      ['Scholarship Application Deadline', 'Scholarship', 'Ana Reyes', ALL, 'normal', '2026-10-18', '2026-11-30', 'published', p('The Scholarship Office reminds all qualified students that the deadline for submitting applications for the Second Semester scholarship grants is on November 30, 2026.') + p('Applicants must submit the accomplished form, a copy of their grades, and a certificate of indigency at the Student Affairs Office of their campus.'),
       { name: 'Scholarship-Application-Guidelines.pdf', size: 1153434, type: 'pdf' }],
      ['Faculty Meeting Notice', 'Administrative', 'Pedro Cruz', 'Urdaneta', 'normal', '2026-10-12', '2026-11-05', 'pending', p('All faculty members are invited to attend the general faculty meeting on November 4, 2026 at 2:00 PM at the University Auditorium.') + p('The agenda includes the semestral calendar updates, research and extension reports, and the preparations for the Founding Anniversary celebration.'),
       { name: 'Faculty-Meeting-Agenda.docx', size: 100352, type: 'docx' }],
      ['Invitation to Lease', 'Administrative', 'Admin User', 'Lingayen-Main', 'normal', day(-3), day(14), 'published', p('The university invites interested parties to lease commercial spaces within the campus. Interested applicants may secure the lease documents from the Business Affairs Office.') + list3('Submit a letter of intent', 'Attend the pre-bid conference', 'Submit the sealed proposal before the deadline'),
       { name: 'Lease-Invitation.pdf', size: 184320, type: 'pdf' }],
      ['Class suspension due to bad weather', 'Advisory', 'Admin User', 'Urdaneta', 'urgent', day(-4), day(10), 'published', p('Classes at the Urdaneta City Campus are suspended until further notice due to bad weather. Students and staff are advised to stay safe and monitor official advisories.') + list3('Online classes are not required', 'Offices will operate with a skeleton workforce', 'Updates will be posted on the official pages')],
      ['Enrollment schedule for the second semester', 'Academic', 'Registrar', ALL, 'normal', day(-5), day(21), 'published', p('Enrollment for the second semester follows the schedule per college. Students are advised to settle their accounts and to bring a valid ID.') + list3('Check your enrollment date and time', 'Prepare your study load and requirements', 'Proceed to your college for advising'),
       { name: 'Enrollment-Schedule.pdf', size: 262144, type: 'pdf' }],
      ['Notice of schedule change for final examinations', 'Academic', 'Registrar', 'Alaminos', 'normal', day(-8), day(6), 'published', p('The final examination schedule at the Alaminos City Campus has been moved. Students should check the revised schedule posted at their department offices.')],
      ['Call for scholarship applications', 'Scholarship', 'Ana Reyes', ALL, 'normal', day(-12), day(18), 'published', p('Qualified students are invited to apply for the available scholarship grants. Applications are accepted at the Student Affairs Office of each campus.')],
      ['Reminder on submission of requirements', 'Administrative', 'Admin User', 'Bayambang', 'normal', day(-14), day(9), 'published', p('Students with pending requirements are reminded to submit them to the Registrar\'s Office before the deadline to avoid delays in processing.') + list3('Photocopy of birth certificate', 'Good moral certificate', 'Updated photo'),
       { name: 'Requirements-Checklist.pdf', size: 92160, type: 'pdf' }],
      ['Enrollment Schedule for Freshmen', 'Academic', 'Registrar', ALL, 'normal', '2026-10-26', day(40), 'published', p('Incoming freshmen should follow the enrollment schedule per college. Bring your admission slip and a valid ID.')],
      ['Library Hours During Semester Break', 'Advisory', 'Viexi Arwan', 'Lingayen-Main', 'normal', '2026-10-20', day(25), 'published', p('The library will close at 5:00 PM during the semester break.')],
      ['Water Interruption This Week', 'Advisory', 'Admin User', 'Urdaneta', 'urgent', '2026-11-08', day(2), 'published', p('Water supply will be interrupted for pipe repairs. Please store water in advance.')],
      ['Campus Clean-up Drive', 'Administrative', 'Pedro Cruz', 'Binmaley', 'normal', '2026-11-01', day(12), 'draft', p('Volunteers are needed for the clean-up drive. Sign-up sheets are at the student affairs office.')]
    ];
    return rows.map(function (r, i) {
      /* r[9] (optional) is the attachment: only name, size and type are kept for sample data.
         "Last updated" starts as the date posted. */
      return { id: 'ann_seed_' + (i + 1), title: r[0], category: r[1], author: r[2], campus: r[3], priority: r[4],
               publishedAt: r[5], expiresAt: r[6], status: r[7], content: r[8], attachment: r[9] || null,
               createdAt: stamp(i), updatedAt: new Date(r[5] + 'T09:00:00').toISOString() };
    });
  }

  function eventCategories() {
    return [
      { id: 'cat_academic', name: 'Academic', description: 'Lectures, forums, and academic programs' },
      { id: 'cat_cultural', name: 'Cultural', description: 'Arts, festivals, and heritage events' },
      { id: 'cat_sports', name: 'Sports', description: 'Intramurals and athletic meets' },
      { id: 'cat_seminar', name: 'Seminar', description: 'Workshops and trainings' },
      { id: 'cat_handbooks', name: 'Handbooks', description: 'Student and employee handbooks' },
      { id: 'cat_research', name: 'Research', description: 'Symposia, congresses, and research forums' }
    ].map(function (c, i) { c.createdAt = stamp(i); c.updatedAt = stamp(i); return c; });
  }

  /* ---- Events. Dates are relative to the first load, so Upcoming / Ongoing / Completed all show up.
     Row: [title, categoryId, start, end, startTime, endTime, venue, organizer, campus, state, description, banner] */
  function events() {
    var rows = [
      ['Research Congress 2026', 'cat_research', day(3), day(3), '08:00', '17:00', 'PSU Convention Center', 'Research Office', 'Lingayen-Main', 'published', 'Researchers present their latest work in parallel sessions.'],
      ['Founding Anniversary', 'cat_cultural', day(11), day(11), '09:00', '', 'Main Campus Grounds', 'Office of the President', ALL, 'published', 'A celebration of the university\'s founding with a parade and program.'],
      ['Nursing Pinning Ceremony', 'cat_academic', day(-1), day(1), '14:00', '', 'Auditorium', 'College of Nursing', 'Lingayen-Main', 'published', 'Graduating nursing students receive their pins.'],
      ['Intramurals Opening', 'cat_sports', '2026-10-05', '2026-10-05', '07:00', '', 'Oval', 'Sports Office', 'Lingayen-Main', 'published', 'Opening parade and ceremonies for the intramurals.'],
      ['Teaching Strategies Workshop', 'cat_academic', day(18), day(18), '13:00', '16:00', 'Faculty Lounge', 'College of Education', 'Lingayen-Main', 'published', 'A hands-on workshop on active learning methods.'],
      ['University Cultural Night', 'cat_cultural', day(-1), day(1), '17:00', '21:00', 'Urdaneta City Cultural Center', 'Supreme Student Council', 'Urdaneta', 'published',
        'Join us for an evening of music, dance and traditional attire.\n\nAnother paragraph goes here. Students, faculty and guests are welcome to attend.', IMG.EVENT],
      ['Career Fair 2026', 'cat_seminar', day(32), day(32), '09:00', '16:00', 'Gymnasium', 'Career Services', 'Lingayen-Main', 'draft', 'Meet employers and learn about job openings.'],
      ['Thesis Writing Seminar', 'cat_research', day(-20), day(-20), '10:00', '12:00', 'Library Hall', 'Graduate School', 'Lingayen-Main', 'published', 'Tips on structuring and defending a thesis.'],
      ['College Admission Test', 'cat_academic', day(9), day(9), '08:00', '12:00', 'Testing Center', 'Admissions Office', 'Lingayen-Main', 'published', 'The entrance examination for incoming students.'],
      ['Research Symposium', 'cat_research', day(13), day(13), '09:00', '16:00', 'Conference Hall', 'Research and Extension Office', 'Alaminos', 'published', 'Faculty and students present completed research projects.'],
      ['Faculty Development Seminar', 'cat_academic', day(16), day(16), '13:00', '17:00', 'Faculty Training Room', 'Human Resource Office', 'Bayambang', 'published', 'A seminar on teaching practice and classroom research.'],
      ['Campus Halloween Program', 'cat_cultural', day(20), day(20), '16:00', '20:00', 'Student Plaza', 'Student Affairs Office', 'Binmaley', 'published', 'Costume contest, games and performances for students.']
    ];
    return rows.map(function (r, i) {
      return { id: 'evt_seed_' + (i + 1), title: r[0], categoryId: r[1], startDate: r[2], endDate: r[3], startTime: r[4], endTime: r[5],
               venue: r[6], organizer: r[7], campus: r[8], state: r[9], description: r[10], banner: r[11] || '', createdAt: stamp(i), updatedAt: stamp(i) };
    });
  }

  /* Sample data for modules owned by teammates (Documents, Faculty & Staff).
     Replace these when those modules are integrated. */
  function documents() {
    return [
      ['Enrollment Guide.pdf', 'PDF', '2026-10-10', 'Step-by-step guide to online and on-site registration.'],
      ['Student Handbook 2026-2027.pdf', 'PDF', '2026-08-01', 'Rules, rights and services for all students.'],
      ['Scholarship Application Form.docx', 'DOCX', '2026-09-15', 'Fillable form for scholarship applicants.'],
      ['Academic Calendar AY 2026-2027.pdf', 'PDF', '2026-07-20', 'Important dates for the academic year.'],
      ['Research Ethics Guidelines.pdf', 'PDF', '2026-06-30', 'Ethical standards for faculty and student research.'],
      ['Campus Map.pdf', 'PDF', '2026-06-12', 'Map of buildings, offices and facilities.']
    ].map(function (r, i) {
      return { id: 'doc_seed_' + (i + 1), title: r[0], fileType: r[1], date: r[2], summary: r[3] };
    });
  }

  function faculty() {
    return [
      ['Dr. Maria Santos', 'Professor', 'College of Nursing', 'maria.santos@example.edu', 'Teaches community health nursing and leads the clinical training program.'],
      ['Engr. Ramon Dela Cruz', 'Associate Professor', 'College of Engineering', 'ramon.delacruz@example.edu', 'Specializes in structural design and heads the engineering research group.'],
      ['Prof. Liza Manalo', 'Assistant Professor', 'College of Education', 'liza.manalo@example.edu', 'Handles courses on curriculum development and assessment.'],
      ['Dr. Jose Villanueva', 'Dean', 'College of Arts and Sciences', 'jose.villanueva@example.edu', 'Oversees academic programs in the humanities and natural sciences.'],
      ['Ms. Carmela Ortiz', 'University Registrar', 'Registrar\'s Office', 'carmela.ortiz@example.edu', 'Manages student records, registration and graduation clearance.'],
      ['Mr. Benito Flores', 'Librarian', 'University Library', 'benito.flores@example.edu', 'Coordinates library services and the digital collection.']
    ].map(function (r, i) {
      return { id: 'fac_seed_' + (i + 1), name: r[0], position: r[1], department: r[2], email: r[3], summary: r[4] };
    });
  }

  return { news: news, announcements: announcements, eventCategories: eventCategories, events: events, documents: documents, faculty: faculty };
})();
